<?php
declare(strict_types=1);
namespace MarketForecast\Tests;
use MarketForecast\Reports\{DailyTextRenderer,ReportArchive};use PHPUnit\Framework\TestCase;
final class ReportArchiveTest extends TestCase { public function testTextAndArchiveAreDeterministic():void{$v=['title'=>'Daily','report_date'=>'2026-01-01','experiment'=>'EXP-001','summary_cards'=>[['label'=>'پیش‌بینی‌های امروز','value'=>'2']],'pair_summary'=>['eligible'=>1,'resolved'=>0],'empty_states'=>['frf'=>'هنوز دادهٔ واقعی کافی برای محاسبهٔ FRF وجود ندارد.'],'health_rows'=>[['label'=>'وضعیت سیستم','value'=>'سالم']]];$text=(new DailyTextRenderer())->render($v);self::assertStringContainsString('FRF 2.0',$text);self::assertStringContainsString('زوج‌های واجد شرایط: 1',$text);self::assertStringNotContainsString('{',$text);$d=sys_get_temp_dir().'/reports-'.bin2hex(random_bytes(3));$a=new ReportArchive();$x=$a->save($d,'2026-01-01','<h1>safe</h1>');$y=$a->save($d,'2026-01-01','<h1>changed</h1>');self::assertTrue($x['created']);self::assertFalse($y['created']);self::assertSame($x['hash'],$y['hash']);@unlink($x['path']);@rmdir($d);} public function testStockAndCryptoArchivesAreDistinctOnTheSameDate():void{$d=sys_get_temp_dir().'/reports-'.bin2hex(random_bytes(3));$a=new ReportArchive();$stock=$a->save($d,'2026-01-01','<h1>stock</h1>','stock');$crypto=$a->save($d,'2026-01-01','<h1>crypto</h1>','crypto');self::assertTrue($stock['created']);self::assertTrue($crypto['created']);self::assertNotSame($stock['path'],$crypto['path']);@unlink($stock['path']);@unlink($crypto['path']);@rmdir($d);} }
